#include <iostream>
#include <vector>
#include <map>
#include <climits>
using namespace std;

const long long MOD = 1000000007;

struct Mod {
    long long v;

    Mod(long long val = 0) {
        v = val % MOD;
        if (v < 0) v += MOD;
    }

    static long long modInverse(long long a, long long m = MOD) {
        long long g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            long long q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + m : x;
    }

    explicit operator int() const { return (int)v; }

    Mod& operator+=(const Mod& other) {
        v += other.v;
        if (v >= MOD) v -= MOD;
        return *this;
    }

    Mod& operator-=(const Mod& other) {
        v -= other.v;
        if (v < 0) v += MOD;
        return *this;
    }

    Mod& operator*=(const Mod& other) {
        v = (v * other.v) % MOD;
        return *this;
    }

    Mod& operator/=(const Mod& other) {
        return *this *= Mod(modInverse(other.v));
    }

    friend Mod operator+(const Mod& a, const Mod& b) { return Mod(a) += b; }
    friend Mod operator-(const Mod& a, const Mod& b) { return Mod(a) -= b; }
    friend Mod operator*(const Mod& a, const Mod& b) { return Mod(a) *= b; }
    friend Mod operator/(const Mod& a, const Mod& b) { return Mod(a) /= b; }

    Mod& operator++() {
        v = (v == MOD - 1) ? 0 : v + 1;
        return *this;
    }

    Mod& operator--() {
        v = (v == 0) ? MOD - 1 : v - 1;
        return *this;
    }

    Mod operator++(int) { Mod tmp = *this; ++(*this); return tmp; }
    Mod operator--(int) { Mod tmp = *this; --(*this); return tmp; }

    Mod operator-() const {
        return v == 0 ? 0 : MOD - v;
    }

    bool operator==(const Mod& other) const { return v == other.v; }
    bool operator!=(const Mod& other) const { return v != other.v; }

    Mod inv() const {
        return Mod(modInverse(v));
    }

    Mod pow(long long p) const {
        Mod base = *this, result = 1;
        while (p > 0) {
            if (p & 1) result *= base;
            base *= base;
            p >>= 1;
        }
        return result;
    }
};

int main() {
    int N;
    cin >> N;
    vector<vector<Mod>> prob(N, vector<Mod>(N));
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            int p;
            cin >> p;
            prob[i][j] = Mod(p) / Mod(100);
        }

    vector<vector<int>> count_by_popcount(N + 1);
    vector<int> lookup(1 << N, -1);
    for (int m = 0; m < (1 << N); ++m) {
        int c = __builtin_popcount(m);
        lookup[m] = (int)count_by_popcount[c].size();
        count_by_popcount[c].push_back(m);
    }

    map<long long, Mod> current_states;
    current_states[1LL << lookup[0]] = 1;

    for (int layer = 0; layer < N; ++layer) {
        map<long long, Mod> next_states;
        for (int mask = 0; mask < (1 << N); ++mask) {
            Mod prod = 1;
            for (int r = 0; r < N; ++r) {
                bool bit_set = (mask >> r) & 1;
                prod *= bit_set ? prob[layer][r] : (Mod(1) - prob[layer][r]);
            }
            for (auto& p : current_states) {
                long long msk = p.first;
                Mod pval = p.second;
                long long new_msk = 0;
                for (int m : count_by_popcount[layer]) {
                    if ((msk >> lookup[m]) & 1) {
                        for (int i = 0; i < N; ++i) {
                            if (((mask >> i) & 1) && ((m >> i) & 1) == 0) {
                                new_msk |= 1LL << lookup[m | (1 << i)];
                            }
                        }
                    }
                }
                next_states[new_msk] += pval * prod;
            }
        }
        current_states = move(next_states);
    }

    Mod total = 0;
    int last_idx = lookup[(1 << N) - 1];
    for (auto& p : current_states) {
        if ((p.first >> last_idx) & 1) total += p.second;
    }
    cout << (int)total << "\n";
}
